{"success": true, "name": "whatsapp-email-campaign-control", "file": "scripts/wa_cdp_batch.py", "content": "#!/usr/bin/env python3
"""Envia uma mensagem do WhatsApp Web em lote por CDP direto (fallback do controlador).

Uso:
    python wa_cdp_batch.py --contacts contatos.json --text-file msg.txt
    python wa_cdp_batch.py --contacts contatos.json --text "..." --greet "Bom dia!"
    python wa_cdp_batch.py --contacts contatos.json --text "..." --only 37557,83358

contatos.json: [{"last5": "37557", "name": "Regis"}] ou ["37557", ...]

Só usa o caminho já comprovado: busca pelos dígitos → abre com Enter na busca → confere o
cabeçalho → insertText + Enter, uma bolha por chamada. Texto com quebra de linha é recusado: o composer é
Lexical e `execCommand('insertText')` descarta `\n` (multilinha exige digitação real, ver
references/whatsapp-web-dom.md).

Pré-requisito: app Electron aberto com o WhatsApp Web na tela (depurador em 127.0.0.1:9222).
"""
import argparse
import base64
import json
import os
import socket
import struct
import sys
import time
import urllib.request


class WS:
    def __init__(self, url, timeout=180):
        assert url.startswith("ws://"), url
        hostport, _, path = url[5:].partition("/")
        host, _, port = hostport.partition(":")
        self.sock = socket.create_connection((host, int(port or 80)), timeout=timeout)
        self.sock.settimeout(timeout)
        key = base64.b64encode(os.urandom(16)).decode()
        self.sock.sendall(
            (
                f"GET /{path} HTTP/1.1\r\nHost: {hostport}\r\nUpgrade: websocket\r\n"
                f"Connection: Upgrade\r\nSec-WebSocket-Key: {key}\r\n"
                f"Sec-WebSocket-Version: 13\r\n\r\n"
            ).encode()
        )
        buf = b""
        while b"\r\n\r\n" not in buf:
            chunk = self.sock.recv(4096)
            if not chunk:
                raise RuntimeError("handshake fechado")
            buf += chunk
        head, _, self.buf = buf.partition(b"\r\n\r\n")
        if b" 101" not in head.split(b"\r\n")[0]:
            raise RuntimeError("handshake recusado: " + head[:120].decode("latin-1"))

    def _recv_exact(self, n):
        while len(self.buf) < n:
            chunk = self.sock.recv(65536)
            if not chunk:
                raise RuntimeError("socket fechado")
            self.buf += chunk
        out, self.buf = self.buf[:n], self.buf[n:]
        return out

    def send_text(self, text):
        payload = text.encode()
        header = bytearray([0x81])
        n = len(payload)
        if n < 126:
            header.append(0x80 | n)
        elif n < 65536:
            header.append(0x80 | 126)
            header += struct.pack(">H", n)
        else:
            header.append(0x80 | 127)
            header += struct.pack(">Q", n)
        mask = os.urandom(4)
        header += mask
        self.sock.sendall(bytes(header) + bytes(b ^ mask[i % 4] for i, b in enumerate(payload)))

    def recv_text(self):
        data = b""
        while True:
            b1, b2 = self._recv_exact(2)
            opcode, fin, n = b1 & 0x0F, b1 & 0x80, b2 & 0x7F
            if n == 126:
                n = struct.unpack(">H", self._recv_exact(2))[0]
            elif n == 127:
                n = struct.unpack(">Q", self._recv_exact(8))[0]
            if b2 & 0x80:
                mask = self._recv_exact(4)
                raw = bytearray(self._recv_exact(n))
                for i in range(n):
                    raw[i] ^= mask[i % 4]
                payload = bytes(raw)
            else:
                payload = self._recv_exact(n)
            if opcode == 0x8:
                raise RuntimeError("servidor fechou o ws")
            if opcode == 0x9:
                self.sock.sendall(bytes([0x8A, 0x80]) + os.urandom(4))
                continue
            if opcode in (0x1, 0x0):
                data += payload
                if fin:
                    return data.decode("utf-8", "replace")


class CDP:
    def __init__(self, url):
        self.ws = WS(url)
        self.id = 0

    def eval(self, expression):
        self.id += 1
        mid = self.id
        self.ws.send_text(
            json.dumps(
                {
                    "id": mid,
                    "method": "Runtime.evaluate",
                    "params": {
                        "expression": expression,
                        "awaitPromise": True,
                        "returnByValue": True,
                        "userGesture": True,
                    },
                }
            )
        )
        while True:
            msg = json.loads(self.ws.recv_text())
            if msg.get("id") != mid:
                continue
            if "error" in msg:
                raise RuntimeError(str(msg["error"])[:300])
            res = msg.get("result") or {}
            if res.get("exceptionDetails"):
                raise RuntimeError(str(res["exceptionDetails"])[:400])
            return (res.get("result") or {}).get("value")


def whatsapp_target(port=9222):
    targets = json.load(urllib.request.urlopen(f"http://127.0.0.1:{port}/json/list", timeout=10))
    for t in targets:
        if t.get("type") == "page" and "web.whatsapp.com" in (t.get("url") or ""):
            return t
    raise SystemExit("aba do WhatsApp Web nao encontrada em 127.0.0.1:%d" % port)


# Uma bolha (ou duas, com greeting) por contato; confere o cabeçalho antes de digitar.
JS = r"""
(async (LAST5, MSG, GREET) => {
  const sleep = ms => new Promise(r => setTimeout(r, ms));
  const out = {};
  const inp = [...document.querySelectorAll('input[type="text"]')].find(i => i.offsetParent !== null);
  if (!inp) return JSON.stringify({error: 'campo de busca ausente'});
  const setter = Object.getOwnPropertyDescriptor(window.HTMLInputElement.prototype, 'value').set;
  inp.focus(); setter.call(inp, ''); inp.dispatchEvent(new Event('input', {bubbles: true}));
  await sleep(200);
  setter.call(inp, LAST5); inp.dispatchEvent(new Event('input', {bubbles: true}));
  await sleep(1100);
  const row = document.querySelector('#pane-side [role="gridcell"]');
  if (!row) return JSON.stringify({error: 'contato fora da lista'});
  const rowTitle = row.querySelector('[data-testid="cell-frame-title"] span[title]')?.getAttribute('title') || '';
  out.rowTitle = rowTitle;
  // Enter no campo de busca abre o primeiro resultado. Nunca clique por coordenada: o
  // elementFromPoint acerta a barra de navegacao quando a linha nao esta ali e abre Status/Stories.
  inp.focus();
  inp.dispatchEvent(new KeyboardEvent('keydown', {key: 'Enter', code: 'Enter', keyCode: 13, which: 13, bubbles: true, cancelable: true}));
  await sleep(1400);
  const hdrFull = document.querySelector('#main header')?.innerText || '';
  out.hdr = hdrFull.replace(/\n/g, '|').slice(0, 40);
  const norm = s => (s || '').replace(/\s+/g, ' ').trim().toLowerCase();
  const ok = hdrFull.replace(/\D/g, '').includes(LAST5) || (rowTitle && norm(hdrFull).includes(norm(rowTitle)));
  if (!ok) return JSON.stringify({...out, abort: 'cabecalho nao confere'});
  const ce = document.querySelector('#main footer div[contenteditable="true"]');
  if (!ce) return JSON.stringify({...out, abort: 'composer ausente'});
  const send = (t) => {
    ce.focus();
    document.execCommand('insertText', false, t);
    ce.dispatchEvent(new KeyboardEvent('keydown', {key: 'Enter', code: 'Enter', keyCode: 13, which: 13, bubbles: true, cancelable: true}));
  };
  if (GREET) { send(GREET); await sleep(800); }
  send(MSG);
  await sleep(900);
  out.typed = (ce.innerText || '').length;
  out.last = [...document.querySelectorAll('#main [data-testid="msg-container"]')].slice(-2).map(m => (m.innerText || '').replace(/\n/g, '|').slice(0, 45));
  return JSON.stringify(out);
})(%s, %s, %s)
"""


def main():
    ap = argparse.ArgumentParser()
    ap.add_argument("--contacts", required=True, help="JSON com last5 (e opcionalmente name)")
    ap.add_argument("--text")
    ap.add_argument("--text-file")
    ap.add_argument("--greet", default="", help='bolha curta antes do texto, ex.: "Bom dia!"')
    ap.add_argument("--only", default="", help="lista de last5 separada por virgula")
    ap.add_argument("--port", type=int, default=9222)
    ap.add_argument("--delay", type=float, default=0.4)
    ap.add_argument("--dry-run", action="store_true", help="so lista os contatos")
    args = ap.parse_args()

    text = args.text or (open(args.text_file, encoding="utf-8").read().strip() if args.text_file else None)
    if not text:
        raise SystemExit("informe --text ou --text-file")
    if "\n" in text.strip():
        raise SystemExit(
            "texto com quebra de linha: execCommand('insertText') descarta \\n — use um paragrafo "
            "unico ou digitacao real (browser_type), ver references/whatsapp-web-dom.md"
        )

    raw = json.load(open(args.contacts, encoding="utf-8"))
    contacts = [c if isinstance(c, dict) else {"last5": str(c)} for c in raw]
    contacts = [c for c in contacts if str(c.get("last5", "")).strip()]
    only = {s.strip() for s in args.only.split(",") if s.strip()}
    if only:
        contacts = [c for c in contacts if str(c["last5"]) in only]
    if not contacts:
        raise SystemExit("nenhum contato a enviar")
    if args.dry_run:
        print(json.dumps(contacts, ensure_ascii=False))
        return

    cdp = CDP(whatsapp_target(args.port)["webSocketDebuggerUrl"])
    results = []
    for c in contacts:
        last5 = str(c["last5"])
        try:
            data = json.loads(cdp.eval(JS % (json.dumps(last5), json.dumps(text), json.dumps(args.greet))))
        except Exception as exc:  # noqa: BLE001 - reportado por contato
            data = {"error": f"{type(exc).__name__}: {str(exc)[:160]}"}
        data["name"] = c.get("name") or last5
        results.append(data)
        print(json.dumps(data, ensure_ascii=False), flush=True)
        time.sleep(args.delay)

    ok = [r for r in results if not r.get("error") and not r.get("abort") and r.get("typed")]
    print(f"\nRESUMO: {len(ok)}/{len(results)} enviados", flush=True)
    if len(ok) != len(results):
        print("nao enviados:", json.dumps([r["name"] for r in results if r not in ok], ensure_ascii=False))
        sys.exit(1)


if __name__ == "__main__":
    main()
